# Code generated by Claude
"""
The gravity feedforward (src/gravity_ff.py, M185): ctrl = q_target + tau_ff / kp, gravity of the arm's OWN bodies at the measured pose.

    MUJOCO_GL=egl python experiments/gravity_ff_test.py

1. The calculated torque equals the torque MuJoCo's gravcomp applies (qfrc_gravcomp of a model built with the old "physics" setting), at the zombie pose and at the extended ready pose, for all 14 arm joints
   and the two grippers: the calculation is right, and (because gravcomp is on the same bodies) it is the arm-only torque.
2. A held object's weight is not in it: the torque is unchanged (to rounding, 1e-12 N m) when the beaker's mass is 10 times larger, and when the plate and the battery masses change; the bodies it uses are only the arms' own
   (names openarm_<side>_<link, hand, finger>).
3. With the feedforward and NO physics gravcomp the arms hold the poses as the old setting did (real gains): every joint within 0.05 degrees, the hand within 1 mm, still at the end (the criteria of
   arm_sag_test); and the torque needed is inside the motors' caps at these poses.
4. The ctrl rule: a target outside the joint range is clipped to the range before tau_ff / kp is added, and the actuators' ctrlrange is widened by torque limit / kp so the sum is not clipped
   (physics setting: the range is the joint range).
5. The copy of the real gains in docs/openarm_control_gains.yaml equals the numbers of robot_specs.
"""

import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
import os  # noqa: E402

if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src import robot_specs  # noqa: E402
from src.gravity_ff import ArmGravityFeedforward  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.simulator import RobotSimulator  # noqa: E402
from src.task_config import TASK_CFG  # noqa: E402

results = []
SIDES = ("left", "right")
POSES = {"zombie (home)": {"left": TASK_CFG["home_q_left"], "right": TASK_CFG["home_q_right"]},
         "extended (ready)": {"left": TASK_CFG["ready_q"], "right": TASK_CFG["home_q_right"]}}


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}", flush=True)


def make(mode):
    robot_specs.ARM_ACTUATOR_SPECS["gravity_comp"] = mode
    return RobotSimulator(pedestal_lift=robot_specs.PEDESTAL_SPECS, cameras=None)


def acts(m):
    ids = {s: arm_ids(m, s) for s in SIDES}
    return {s: list(ids[s]["act"]) for s in SIDES}, {s: [ids[s]["gripper"]] for s in SIDES}, ids


def place(m, d, pose, ids):
    mujoco.mj_resetData(m, d)
    d.qpos[0:7] = [0.0, 0.0, 0.1527, 1.0, 0.0, 0.0, 0.0]
    d.qpos[m.joint("pedestal_joint").qposadr[0]] = TASK_CFG["pedestal_q"]
    for s in SIDES:
        for j, q in zip(ids[s]["qadr"], pose[s]):
            d.qpos[j] = q
        for j in ids[s]["finger_jnt"]:
            d.qpos[m.jnt_qposadr[j]] = 0.044
    mujoco.mj_forward(m, d)


def main():
    phys, ffs = make("physics"), make("feedforward")
    pa, pf, pids = acts(phys.model)
    fa, ff_, fids = acts(ffs.model)
    gff = ArmGravityFeedforward(ffs.model, fa, ff_)
    print("1. the calculated torque against MuJoCo's gravcomp torque")
    for pn, pose in POSES.items():
        place(phys.model, phys.data, pose, pids)
        place(ffs.model, ffs.data, pose, fids)
        tau = gff.torques(ffs.data)
        ref = []
        for s in SIDES:
            ref += [phys.data.qfrc_gravcomp[int(phys.model.jnt_dofadr[phys.model.actuator_trnid[a, 0]])] for a in pa[s]]
            ref.append(sum(phys.data.qfrc_gravcomp[int(phys.model.joint(f"openarm_{s}_finger_joint{k}").dofadr[0])] for k in (1, 2)))
        ref = np.array(ref)
        err = float(np.max(np.abs(tau - ref)))
        check(f"{pn}: all 16 values (14 joints + 2 grippers) agree with qfrc_gravcomp", err < 1e-9 and np.max(np.abs(ref)) > 1.0, f"largest difference {err:.2e}, largest torque {np.max(np.abs(ref)):.2f} N m")
        print("      tau_ff left arm 1..7 (N m):", np.round(tau[:7], 3).tolist())

    print("\n2. a held object's weight is not in it")
    place(ffs.model, ffs.data, POSES["extended (ready)"], fids)
    base = gff.torques(ffs.data).copy()
    m = ffs.model
    saved = m.body_mass.copy()
    for name in ("task_beaker", "task_hotplate", "battery"):
        try:
            b = m.body(name).id
        except KeyError:
            continue
        m.body_mass[b] *= 10.0
    diff = float(np.max(np.abs(gff.torques(ffs.data) - base)))                  # not bit-identical: the battery is part of the robot's tree and moves the tree's reference point of the Jacobians (rounding only)
    m.body_mass[:] = saved
    check("the torque is unchanged (to 1e-12 N m, rounding) with the beaker, hotplate and battery masses 10 times larger", diff < 1e-12, f"largest difference {diff:.2e} N m")
    names = [m.body(b).name for b, _ in gff.bodies]
    check("every body it uses is an arm's own link, hand or finger", all(n.startswith(("openarm_left_", "openarm_right_")) for n in names) and len(names) >= 14, f"{len(names)} bodies, e.g. {names[:3]}")
    b4 = m.body("openarm_left_link4").id
    m.body_mass[b4] *= 2.0
    changed = ArmGravityFeedforward(ffs.model, fa, ff_)                        # reads the masses when built
    check("sanity: a change of an arm link's mass DOES change it", not np.allclose(changed.torques(ffs.data), base))
    m.body_mass[:] = saved

    print("\n3. the arms hold with the feedforward and no physics gravcomp")
    caps = np.array([robot_specs.ARM_ACTUATOR_SPECS["joints"][i]["torque_nm"] for _ in SIDES for i in range(1, 8)])
    for pn, pose in POSES.items():
        mm, d = ffs.model, ffs.data
        place(mm, d, pose, fids)
        ctrl = np.zeros(mm.nu)
        ctrl[mm.actuator(robot_specs.PEDESTAL_SPECS["actuator_name"]).id] = TASK_CFG["pedestal_q"]
        for s in SIDES:
            for a, q in zip(fa[s], pose[s]):
                ctrl[a] = q
            ctrl[ff_[s]] = 0.044
        wheels = [mm.actuator("left_motor").id, mm.actuator("right_motor").id]
        bd = int(mm.jnt_dofadr[mm.joint("base_float").id])
        tcp = {s: mm.body(f"openarm_{s}_hand_tcp").id for s in SIDES}
        base_b = mm.body("base_link").id
        ref = {s: d.xpos[tcp[s]] - d.xpos[base_b] for s in SIDES}
        peak = np.zeros(14)
        for k in range(int(3.0 * robot_specs.PHYSICS_HZ)):
            d.ctrl[:] = ctrl
            d.ctrl[wheels] = 0.0
            gff.apply(d.ctrl, d)
            d.qvel[bd:bd + 2] = 0.0
            d.qvel[bd + 3:bd + 6] = 0.0
            mujoco.mj_step(mm, d)
            peak = np.maximum(peak, np.abs(np.concatenate([d.actuator_force[fa[s]] for s in SIDES])))
        err = np.degrees(np.abs(np.array([[d.qpos[j] - q for j, q in zip(fids[s]["qadr"], pose[s])] for s in SIDES]))).max()
        speed = max(abs(d.qvel[v]) for s in SIDES for v in fids[s]["vadr"])
        hand = max(float(np.linalg.norm((d.xpos[tcp[s]] - d.xpos[base_b]) - ref[s])) for s in SIDES) * 1000
        check(f"{pn}: every joint within 0.05 degrees, the hand within 1 mm, the arms still", err < 0.05 and hand < 1.0 and speed < 1e-3, f"{err:.4f} deg, {hand:.3f} mm, {speed:.1e} rad/s")
        check(f"{pn}: the torque used stays inside the caps", bool(np.all(peak < caps)), f"largest share of cap {np.max(peak / caps):.2f}")

    print("\n4. the ctrl rule")
    mm = ffs.model
    a = fa["left"][3]
    lo, hi = mm.jnt_range[mm.actuator_trnid[a, 0]]
    cap = robot_specs.ARM_ACTUATOR_SPECS["joints"][4]
    ctrl = np.zeros(mm.nu)
    ctrl[a] = hi + 1.0
    ctrl2 = ctrl.copy()
    gff.apply_offsets(ctrl2, np.full(len(gff.ids), 0.05))
    k = list(gff.ids).index(a)
    check("a target above the joint's range is clipped to the range, then tau_ff / kp is added", abs(ctrl2[a] - (hi + 0.05)) < 1e-12, f"{ctrl2[a]:.4f} (range top {hi:.4f})")
    check("the feedforward model's ctrlrange is the joint range widened by torque limit / kp; the physics model's is the joint range", np.allclose(mm.actuator_ctrlrange[a], [lo - cap['torque_nm'] / cap['kp'], hi + cap['torque_nm'] / cap['kp']]) and np.allclose(phys.model.actuator_ctrlrange[pa["left"][3]], phys.model.jnt_range[phys.model.actuator_trnid[pa["left"][3], 0]]))

    print("\n5. the tracked copy of the real gains")
    import re
    txt = (PROJECT_ROOT / "docs" / "openarm_control_gains.yaml").read_text()
    vals = {}
    cur = None
    for line in txt.splitlines():
        mt = re.match(r"^(joint\d|hand):", line)
        if mt:
            cur = mt.group(1)
        mt = re.match(r"^\s+(kp|kd): ([0-9.]+)", line)
        if mt and cur:
            vals[(cur, mt.group(1))] = float(mt.group(2))
    ok = all(vals[(f"joint{i}", "kp")] == j["kp"] and vals[(f"joint{i}", "kd")] == j["kv"] for i, j in robot_specs.ARM_ACTUATOR_SPECS["joints"].items())
    check("kp and kd of joints 1..7 in the tracked file equal robot_specs.ARM_ACTUATOR_SPECS", ok and len(vals) == 16)
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
